def test_dedupe_transcripts_keeps_last_record_and_sorts_by_day_then_id():
    earlier = {"id": "a", "day": 5, "flagged": True}
    later = {"id": "a", "day": 2, "flagged": False}
    same_day = {"id": "b", "day": 2, "flagged": True}
    first_day = {"id": "z", "day": 1, "flagged": None}
    assert dedupe_transcripts([earlier, same_day, first_day, later]) == [first_day, later, same_day]


